#!/bin/bash
# usage: targets/wamr/build.sh [out_dir]
#   builds iwasm (fast interpreter only) with switch / computed-goto / tail-call dispatch
#   env: CCS="gcc clang"  MODES="switch cgoto tail tailpn"  JOBS=4  OPT=(cmake Release: -O3)
#   tail/tailpn: interpreter generated by gen_tail.py (tailpn adds preserve_none)
#   result: <out_dir>/bin/iwasm_<mode>_<cc>
set -e
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
TAG=WAMR-2.4.6
SRC=$ROOT/third_party/wamr
OUT=$(mkdir -p "${1:-$ROOT/build/wamr}" && cd "${1:-$ROOT/build/wamr}" && pwd)
CCS=${CCS:-"gcc clang"}
MODES=${MODES:-"switch cgoto tail tailpn"}
JOBS=${JOBS:-4}
# OPT="" keeps cmake's Release flags (-O3 -DNDEBUG); OPT=-O2 etc. overrides the level
# EXTRA_CMAKE="-D..." extra cmake options, applied after the defaults (analysis/wamr_spec.sh)
OPT=${OPT:-}

if [ ! -d "$SRC" ]; then
    git clone -q --depth 1 --branch $TAG https://github.com/bytecodealliance/wasm-micro-runtime.git "$SRC"
fi

COMMON=(-DCMAKE_BUILD_TYPE=Release -DCMAKE_EXPORT_COMPILE_COMMANDS=ON
        -DWAMR_BUILD_INTERP=1 -DWAMR_BUILD_FAST_INTERP=1
        -DWAMR_BUILD_AOT=0 -DWAMR_BUILD_JIT=0 -DWAMR_BUILD_FAST_JIT=0
        -DWAMR_BUILD_SIMD=0 -DWAMR_BUILD_LIBC_WASI=1 -DWAMR_BUILD_LIBC_BUILTIN=1)

INTERP=core/iwasm/interpreter/wasm_interp_fast.c

# generate the tail-call interpreter for build dir $1 (configured) and source tree $2
gen_tail() {
    local b=$1 tree=$2
    local flags
    flags=$(python3 -I -c '
import json, shlex, sys
cc = json.load(open(sys.argv[1] + "/compile_commands.json"))
e = [x for x in cc if x["file"].endswith("wasm_interp_fast.c")][0]
a = shlex.split(e["command"])[1:]
out, skip = [], False
for x in a:
    if skip: skip = False; continue
    if x in ("-o", "-c"): skip = True; continue
    if x.endswith(".c"): continue
    out.append(x)
print(" ".join(shlex.quote(x) for x in out))' "$b")
    python3 -I "$HERE/gen_tail.py" mark "$SRC/$INTERP" "$b/marked.c"
    eval "$cc" $flags -I "$tree/core/iwasm/interpreter" -E -P "$b/marked.c" -o "$b/pre.c"
    python3 -I "$HERE/gen_tail.py" gen "$b/pre.c" "$tree/$INTERP" 2> "$b/gen.log"
}

HERE=$ROOT/targets/wamr
mkdir -p "$OUT/bin"
for cc in $CCS; do
    command -v $cc >/dev/null || { echo "skip $cc (not found)" >&2; continue; }
    # some systems (Termux, macOS) ship "gcc" as an alias of clang
    if [ $cc = gcc ] && gcc --version 2>/dev/null | grep -q clang; then echo "skip gcc (it is clang)" >&2; continue; fi
    for mode in $MODES; do
        tree=$SRC
        case $mode in
            switch) FLAGS="-DWASM_ENABLE_LABELS_AS_VALUES=0" ;;
            cgoto)  FLAGS="-DWASM_ENABLE_LABELS_AS_VALUES=1" ;;
            tail)   FLAGS="-DWASM_ENABLE_LABELS_AS_VALUES=1" ;;
            tailpn) FLAGS="-DWASM_ENABLE_LABELS_AS_VALUES=1 -DWAMR_TAIL_PRESERVE_NONE=1" ;;
            *) echo "unknown mode $mode" >&2; exit 1 ;;
        esac
        b=$OUT/obj_${mode}_$cc
        rm -rf "$b"
        if [[ $mode == tail* ]]; then   # private copy of the sources, interpreter replaced
            tree=$OUT/src_${mode}_$cc
            rm -rf "$tree"; mkdir -p "$tree"
            cp -r "$SRC/core" "$SRC/product-mini" "$SRC/build-scripts" "$tree/"
        fi
        RELFLAGS=()
        [ -n "$OPT" ] && RELFLAGS=(-DCMAKE_C_FLAGS_RELEASE="$OPT -DNDEBUG")
        GEN="Unix Makefiles"; command -v ninja >/dev/null && GEN=Ninja
        cmake -S "$tree/product-mini/platforms/linux" -B "$b" -G "$GEN" \
            -DCMAKE_C_COMPILER=$cc "${COMMON[@]}" "${RELFLAGS[@]}" ${EXTRA_CMAKE:-} -DCMAKE_C_FLAGS="$FLAGS" > "$b.cmake.log" 2>&1 \
            || { echo "cmake failed: $b.cmake.log" >&2; exit 1; }
        if [[ $mode == tail* ]]; then
            gen_tail "$b" "$tree" || { echo "tail generation failed ($b)" >&2; exit 1; }
        fi
        cmake --build "$b" -j "$JOBS" --target iwasm > "$b.build.log" 2>&1 \
            || { echo "build failed: $b.build.log" >&2; exit 1; }
        cp "$b/iwasm" "$OUT/bin/iwasm_${mode}_$cc"
    done
done
ls "$OUT/bin"
